-- Manual, idempotent MySQL script for the pt-BR fork (branch feat/chat-pt-br).
-- Translates the public catalog from seed/001_public_catalog.sql and the
-- welcome project from seed/002_welcome_project.sql to pt-BR. Like
-- 023_role_prompt.sql it replaces the built-in payloads, so operator edits
-- to these rows are lost: back up first. Role prompts and rules also ask the
-- agents to write artifacts and replies in Brazilian Portuguese.
-- Values are hex literals of UTF-8 text.
SET NAMES utf8mb4;
START TRANSACTION;
UPDATE sandboxes SET name=CONVERT(X'4578656375c3a7c3a36f206c6f63616c202873c3b3207461726566617320636f6e6669c3a17665697329' USING utf8mb4), payload=CONVERT(X'7b226964223a20226c6f63616c222c20226e616d65223a20224578656375c3a7c3a36f206c6f63616c202873c3b3207461726566617320636f6e6669c3a17665697329222c2022647269766572223a20226c6f63616c227d' USING utf8mb4) WHERE id='local';
UPDATE sandboxes SET name=CONVERT(X'53616e64626f782069736f6c61646f20446f636b6572' USING utf8mb4), payload=CONVERT(X'' USING utf8mb4) WHERE id='generic-docker';
UPDATE dockerfiles SET name=CONVERT(X'416d6269656e746520646520646573656e766f6c76696d656e746f20636f6d756d' USING utf8mb4), payload=CONVERT(X'' USING utf8mb4) WHERE id='generic-backend';
UPDATE rules SET name=CONVERT(X'52656772617320646520656e67656e68617269612065207665726966696361c3a7c3a36f' USING utf8mb4), payload=CONVERT(X'' USING utf8mb4) WHERE id='public-engineering';
UPDATE generic_templates SET name=CONVERT(X'534f5020646520656e7472656761206261636b2d656e64' USING utf8mb4), payload=CONVERT(X'' USING utf8mb4) WHERE id='generic-backend-delivery';
UPDATE generic_templates SET name=CONVERT(X'534f5020646520656e74726567612066726f6e742d656e64' USING utf8mb4), payload=CONVERT(X'' USING utf8mb4) WHERE id='generic-frontend-delivery';
UPDATE generic_templates SET name=CONVERT(X'534f5020646520636f727265c3a7c3a36f206465206465666569746f73' USING utf8mb4), payload=CONVERT(X'' USING utf8mb4) WHERE id='issue-fix-production';
UPDATE generic_templates SET name=CONVERT(X'534f502064652070726f706f7374612064652070726f6475746f' USING utf8mb4), payload=CONVERT(X'' USING utf8mb4) WHERE id='generic-product-delivery';
UPDATE workflows SET name=CONVERT(X'56616c696461c3a7c3a36f20646120706c617461666f726d6120c2b7207363726970742065206170726f7661c3a7c3a36f' USING utf8mb4), payload=CONVERT(X'' USING utf8mb4) WHERE id='welcome-workflow';
UPDATE agents SET name=CONVERT(X'4578656375746f7220646520616c696e68616d656e746f20636f6d20612062617365' USING utf8mb4), payload=CONVERT(X'' USING utf8mb4) WHERE id='baseline-align-resolver';
UPDATE projects SET name='Projeto de demonstração LoopForge', payload=JSON_SET(payload,'$.name','Projeto de demonstração LoopForge','$.description','Experimente o fluxo completo de entrega: criar um requisito, escolher um SOP e acompanhar a execução e a aprovação.') WHERE id='welcome' AND name='LoopForge 体验项目';
COMMIT;
